INSERT INTO "Destination" (city, country, image, description, rating, duration, price, category) VALUES
('Warsaw', 'Poland', 'https://images.unsplash.com/photo-1519197924294-4ba991a11128?w=800&q=80', 'WWII history, vibrant old town, and pierogi culture.', 4.7, '4-6 days', 'From $699', 'Culture'),
('Krakow', 'Poland', 'https://images.unsplash.com/photo-1569591559621-921d4b7ef74b?w=800&q=80', 'Medieval market square, Wawel castle, and Jewish quarter.', 4.8, '3-5 days', 'From $649', 'Culture'),
('Tallinn', 'Estonia', 'https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=800&q=80', 'Best preserved medieval old town in Northern Europe.', 4.9, '3-5 days', 'From $749', 'Culture'),
('Riga', 'Latvia', 'https://images.unsplash.com/photo-1577434639074-0ca8a3b2c6a8?w=800&q=80', 'Art Nouveau architecture and Baltic amber markets.', 4.7, '3-5 days', 'From $699', 'Culture'),
('Vilnius', 'Lithuania', 'https://images.unsplash.com/photo-1587974928442-77dc3e0dba72?w=800&q=80', 'UNESCO baroque old town and bohemian republic of Uzupis.', 4.7, '3-5 days', 'From $679', 'Culture'),
('Helsinki', 'Finland', 'https://images.unsplash.com/photo-1538370965046-79c0d6907d47?w=800&q=80', 'Design capital, saunas, and archipelago island hopping.', 4.8, '4-6 days', 'From $999', 'City'),
('Stockholm', 'Sweden', 'https://images.unsplash.com/photo-1509356843151-3e7d96241e11?w=800&q=80', 'Gamla Stan island, ABBA museum, and Viking history.', 4.8, '4-6 days', 'From $1,099', 'City'),
('Oslo', 'Norway', 'https://images.unsplash.com/photo-1531366936337-7c912a4589a7?w=800&q=80', 'Fjords, Viking ships, and the Munch scream museum.', 4.8, '4-6 days', 'From $1,199', 'Nature'),
('Bergen', 'Norway', 'https://images.unsplash.com/photo-1601134467661-3d775b999c18?w=800&q=80', 'Gateway to the Norwegian fjords and Bryggen wharf.', 4.9, '4-6 days', 'From $1,099', 'Nature'),
('Copenhagen', 'Denmark', 'https://images.unsplash.com/photo-1513622470522-26c3c8a854bc?w=800&q=80', 'Noma dining, Tivoli gardens, and cycling culture.', 4.8, '4-6 days', 'From $1,099', 'City'),
('Reykjavik', 'Iceland', 'https://images.unsplash.com/photo-1504893524553-b855bce32c67?w=800&q=80', 'Northern lights, geysers, and midnight sun adventures.', 5.0, '5-8 days', 'From $1,499', 'Nature'),
('Bucharest', 'Romania', 'https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=800&q=80', 'Little Paris of Eastern Europe with grand boulevards.', 4.6, '3-5 days', 'From $599', 'City'),
('Brasov', 'Romania', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=800&q=80', 'Dracula country, Saxon medieval walls, and Carpathians.', 4.8, '4-6 days', 'From $649', 'Nature'),
('Sofia', 'Bulgaria', 'https://images.unsplash.com/photo-1560726645-82c8b3e2eb71?w=800&q=80', 'Alexander Nevsky cathedral, Vitosha mountain, and rose valley.', 4.6, '3-5 days', 'From $579', 'Culture'),
('Belgrade', 'Serbia', 'https://images.unsplash.com/photo-1595435929690-aa0a7a2f1eba?w=800&q=80', 'Fortress on the Danube, kafanas, and Balkan nightlife.', 4.7, '3-5 days', 'From $599', 'City'),
('Sarajevo', 'Bosnia', 'https://images.unsplash.com/photo-1598978483080-f8843a72b6fc?w=800&q=80', 'Where East meets West, poignant history, and cevapi.', 4.8, '3-5 days', 'From $579', 'Culture'),
('Dubrovnik', 'Croatia', 'https://images.unsplash.com/photo-1555990538-c47d6e76e101?w=800&q=80', 'Game of Thrones backdrop, Adriatic walls, and island hops.', 4.9, '4-6 days', 'From $999', 'Beach'),
('Ljubljana', 'Slovenia', 'https://images.unsplash.com/photo-1571366343168-631c5bcca7a4?w=800&q=80', 'Dragon bridge, castle hill, and Lake Bled gateway.', 4.8, '3-5 days', 'From $799', 'Nature'),
('Bratislava', 'Slovakia', 'https://images.unsplash.com/photo-1549880338-65ddcdfd017b?w=800&q=80', 'Compact castle town on the Danube border with Austria.', 4.6, '2-4 days', 'From $599', 'Culture'),
('Minsk', 'Belarus', 'https://images.unsplash.com/photo-1553899017-4b5b3e74ab46?w=800&q=80', 'Soviet architecture, Stalinka boulevards, and folk art.', 4.4, '3-5 days', 'From $549', 'Culture');
